1	// Black-box tests for the booking rules and the list endpoint of server.mjs.
2	import { test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import http from 'node:http';
5	import { boot, post, request, rawRequest, valid, JSON_TYPE } from './helpers/server-harness.mjs';
6	
7	const MISSING = Symbol('missing');
8	const MSG = {
9	  ct: 'content type must be application/json',
10	  big: 'body too large',
11	  obj: 'body must be a JSON object',
12	  room: 'room must be one of Aurora, Borealis, Cosmos',
13	  title: 'title must be 1 to 80 characters',
14	  date: 'date must be a valid YYYY-MM-DD date',
15	  start: 'start must be HH:MM',
16	  end: 'end must be HH:MM',
17	  order: 'end must be after start',
18	};
19	
20	/** Like the harness assertError, but every assert names its case. */
21	function expectError(res, status, message, label) {
22	  assert.equal(res.status, status, `${label}: status`);
23	  assert.deepEqual(res.json, { error: message }, `${label}: body`);
24	  assert.equal(res.headers['content-type'], JSON_TYPE, `${label}: content-type`);
25	}
26	
27	/** valid() with `over` applied; MISSING removes the key. */
28	function body(over = {}) {
29	  const obj = valid(over);
30	  for (const [k, v] of Object.entries(over)) if (v === MISSING) delete obj[k];
31	  return obj;
32	}
33	
34	const CT = (value) => ({ 'content-type': value });
35	
36	/** Raw POST with a Buffer header line (or none) and an exact Content-Length. */
37	function rawPost(port, headerLine, payload) {
38	  const data = Buffer.isBuffer(payload) ? payload : Buffer.from(payload);
39	  const parts = [Buffer.from('POST /api/bookings HTTP/1.1\r\nHost: x\r\n')];
40	  if (headerLine) parts.push(Buffer.isBuffer(headerLine) ? headerLine : Buffer.from(headerLine), Buffer.from('\r\n'));
41	  parts.push(Buffer.from(`Content-Length: ${data.length}\r\nConnection: close\r\n\r\n`), data);
42	  return rawRequest(port, Buffer.concat(parts));
43	}
44	
45	function chunkedPost(port, payload) {
46	  return new Promise((resolve, reject) => {
47	    const req = http.request({
48	      host: '127.0.0.1', port, method: 'POST', path: '/api/bookings', agent: false,
49	      headers: { 'content-type': 'application/json', 'transfer-encoding': 'chunked' },
50	    }, (res) => {
51	      let text = '';
52	      res.on('data', (c) => { text += c; });
53	      res.on('end', () => resolve({ status: res.statusCode, json: JSON.parse(text) }));
54	    });
55	    req.on('error', reject);
56	    const third = Math.floor(payload.length / 3);
57	    req.write(payload.subarray(0, third));
58	    req.write(payload.subarray(third, 2 * third));
59	    req.end(payload.subarray(2 * third));
60	  });
61	}
62	
63	/** A valid booking JSON text of exactly `bytes` bytes, optionally using 2-byte chars as padding. */
64	function sizedBody(bytes, multibyte) {
65	  const base = JSON.stringify({ ...valid(), pad: '' });
66	  const k = multibyte ? Math.floor((bytes - base.length) / 2) : 0;
67	  const text = JSON.stringify({ ...valid(), pad: 'é'.repeat(k) });
68	  return text + ' '.repeat(bytes - Buffer.byteLength(text));
69	}
70	
71	const hourSlot = (i) => ({ start: `${String(i).padStart(2, '0')}:00`, end: `${String(i).padStart(2, '0')}:30` });
72	
73	// ---------- rule 1 ----------
74	
75	test('rule 1: accepted media type spellings', async (t) => {
76	  const { port } = await boot(t);
77	  const accepted = ['Application/JSON ; charset=x', 'application/json;', 'APPLICATION/JSON'];
78	  for (const [i, ct] of accepted.entries()) {
79	    const res = await post(port, body(hourSlot(i)), CT(ct));
80	    assert.equal(res.status, 201, `accept ${JSON.stringify(ct)}`);
81	  }
82	  const tabbed = ['Content-Type:\tapplication/json\t;x', 'Content-Type: application/json\t;x',
83	    'Content-Type: application/json \t \t; charset=x'];
84	  for (const [i, line] of tabbed.entries()) {
85	    const raw = await rawPost(port, line, JSON.stringify(body(hourSlot(5 + i))));
86	    assert.equal(raw.status, 201, `accept tab padded raw header ${JSON.stringify(line)}`);
87	  }
88	});
89	
90	test('rule 1: rejected media types', async (t) => {
91	  const { port } = await boot(t);
92	  const rejected = ['application/json-patch', 'application/jsonx', 'text/json', 'application/json, text/plain',
93	    ';application/json', 'application/ json', 'application /json'];
94	  for (const ct of rejected) {
95	    expectError(await post(port, body(), CT(ct)), 415, MSG.ct, `reject ${JSON.stringify(ct)}`);
96	  }
97	  expectError(await post(port, body(), {}), 415, MSG.ct, 'missing header');
98	  const text = JSON.stringify(body());
99	  expectError(await rawPost(port, 'Content-Type: ', text), 415, MSG.ct, 'empty header value');
100	  const nbsp = Buffer.concat([Buffer.from('Content-Type:'), Buffer.from([0xa0]), Buffer.from('application/json')]);
101	  expectError(await rawPost(port, nbsp, text), 415, MSG.ct, 'latin1 nbsp padding');
102	});
103	
104	// ---------- rule 2 and rule order ----------
105	
106	test('rule 2: size limits by byte count', async (t) => {
107	  const { port } = await boot(t);
108	  const big = Buffer.alloc(20000, 0x61);
109	  expectError(await post(port, big, CT('text/plain')), 415, MSG.ct, 'bad type beats big body');
110	  expectError(await post(port, Buffer.alloc(10001, 0x7b)), 413, MSG.big, '10001 bytes invalid JSON');
111	  const padded = JSON.stringify(valid()) + ' '.repeat(10001 - JSON.stringify(valid()).length);
112	  expectError(await post(port, padded), 413, MSG.big, '10001 bytes valid booking');
113	  const ok = await post(port, sizedBody(10000, false));
114	  assert.equal(ok.status, 201, '10000 byte body accepted');
115	});
116	
117	test('rule 2: multi-byte characters count as bytes', async (t) => {
118	  const { port } = await boot(t);
119	  const over = JSON.stringify({ ...valid(), pad: 'é'.repeat(9990 - JSON.stringify({ ...valid(), pad: '' }).length) });
120	  assert.equal(over.length, 9990, 'test setup: character count');
121	  assert.ok(Buffer.byteLength(over) > 10000, 'test setup: byte count above limit');
122	  expectError(await post(port, over), 413, MSG.big, 'few chars, many bytes');
123	  const exact = sizedBody(10000, true);
124	  assert.equal(Buffer.byteLength(exact), 10000, 'test setup: exact bytes');
125	  assert.ok(exact.length < 10000, 'test setup: multi-byte chars present');
126	  assert.equal((await post(port, exact)).status, 201, 'exactly 10000 multi-byte bytes');
127	});
128	
129	test('rule 2: chunked uploads', async (t) => {
130	  const { port } = await boot(t);
131	  const tooBig = Buffer.from(JSON.stringify(valid()) + ' '.repeat(10001 - JSON.stringify(valid()).length));
132	  assert.equal(tooBig.length, 10001, 'test setup: chunked size');
133	  const res = await chunkedPost(port, tooBig);
134	  assert.equal(res.status, 413, 'chunked 10001 status');
135	  assert.deepEqual(res.json, { error: MSG.big }, 'chunked 10001 body');
136	  const okRes = await chunkedPost(port, Buffer.from(sizedBody(10000, false)));
137	  assert.equal(okRes.status, 201, 'chunked 10000 accepted');
138	});
139	
140	test('rule order: the first failing rule decides', async (t) => {
141	  const { port } = await boot(t);
142	  const cases = [
143	    ['room before title', { room: 'x', title: '' }, MSG.room],
144	    ['title before date', { title: '', date: 'x' }, MSG.title],
145	    ['date before start', { date: 'x', start: 'x' }, MSG.date],
146	    ['start before end', { start: 'x', end: 'x' }, MSG.start],
147	    ['end before order', { start: '10:00', end: 'x' }, MSG.end],
148	  ];
149	  for (const [label, over, message] of cases) {
150	    expectError(await post(port, body(over)), 400, message, label);
151	  }
152	  expectError(await post(port, '{not json, "room": "x"}'), 400, MSG.obj, 'invalid JSON beats room');
153	});
154	
155	test('rule order: end must be after start beats 409', async (t) => {
156	  const { port } = await boot(t);
157	  assert.equal((await post(port, body())).status, 201, 'seed');
158	  const equal = await post(port, body({ start: '10:30', end: '10:30' }));
159	  expectError(equal, 400, MSG.order, 'equal times inside an existing booking');
160	  const reversed = await post(port, body({ start: '10:30', end: '10:00' }));
161	  expectError(reversed, 400, MSG.order, 'reversed times inside an existing booking');
162	});
163	
164	// ---------- rule 3 ----------
165	
166	test('rule 3: bodies that are not JSON objects', async (t) => {
167	  const { port } = await boot(t);
168	  const bad = ['', ' ', 'null', '[]', '[{}]', '"x"', '0', 'false', '{', '{"room":"Aurora"} x'];
169	  for (const text of bad) {
170	    expectError(await post(port, text), 400, MSG.obj, `body ${JSON.stringify(text)}`);
171	  }
172	  const bom = Buffer.concat([Buffer.from([0xef, 0xbb, 0xbf]), Buffer.from(JSON.stringify(valid()))]);
173	  expectError(await post(port, bom), 400, MSG.obj, 'BOM prefix');
174	  expectError(await post(port, '{}'), 400, MSG.room, 'empty object');
175	});
176	
177	test('rule 3: whitespace and invalid UTF-8', async (t) => {
178	  const { port } = await boot(t);
179	  const ws = await post(port, `\n ${JSON.stringify(valid())} \n`);
180	  assert.equal(ws.status, 201, 'whitespace around object');
181	  const head = '{"room":"Aurora","title":"x';
182	  const tail = '","date":"2026-11-03","start":"12:00","end":"13:00"}';
183	  const titled = await post(port, Buffer.concat([Buffer.from(head), Buffer.from([0xff]), Buffer.from(tail)]));
184	  assert.equal(titled.status, 201, 'invalid byte in title status');
185	  assert.equal(titled.json.title, 'x�', 'invalid byte in title becomes U+FFFD');
186	  const roomHead = Buffer.from('{"room":"Aurora');
187	  const roomTail = Buffer.from('","title":"x","date":"2026-11-03","start":"14:00","end":"15:00"}');
188	  const badRoom = await post(port, Buffer.concat([roomHead, Buffer.from([0xff]), roomTail]));
189	  expectError(badRoom, 400, MSG.room, 'invalid byte in room');
190	});
191	
192	// ---------- rule 4 ----------
193	
194	test('rule 4: room names', async (t) => {
195	  const { port } = await boot(t);
196	  const bad = ['aurora', 'AURORA', ' Aurora', 'Aurora ', 'Aurora\u0000', null, 1, ['Aurora'], MISSING, 'Nebula'];
197	  for (const room of bad) {
198	    const label = `room ${room === MISSING ? 'missing' : JSON.stringify(room)}`;
199	    expectError(await post(port, body({ room })), 400, MSG.room, label);
200	  }
201	  for (const room of ['Borealis', 'Cosmos']) {
202	    assert.equal((await post(port, body({ room }))).status, 201, `room ${room}`);
203	  }
204	  const proto = '{"__proto__":{"room":"Aurora"},"title":"t","date":"2026-11-03","start":"10:00","end":"11:00"}';
205	  expectError(await post(port, proto), 400, MSG.room, '__proto__ room');
206	});
207	
208	// ---------- rule 5 ----------
209	
210	test('rule 5: rejected titles', async (t) => {
211	  const { port } = await boot(t);
212	  const bad = ['', '   ', '\t\n', '　 ', null, 5, ['x'], MISSING, 'x'.repeat(81), ` ${'x'.repeat(81)} `,
213	    '😀'.repeat(41), `${'a'.repeat(79)}😀`];
214	  for (const [i, title] of bad.entries()) {
215	    const label = `title #${i} ${title === MISSING ? 'missing' : JSON.stringify(title)}`;
216	    expectError(await post(port, body({ title })), 400, MSG.title, label);
217	  }
218	});
219	
220	test('rule 5: accepted titles are stored trimmed', async (t) => {
221	  const { port } = await boot(t);
222	  const x80 = 'x'.repeat(80);
223	  const cases = [
224	    ['😀'.repeat(40), '😀'.repeat(40)], [` \t${x80}\t `, x80], ['　hi ', 'hi'], ['﻿hi ', 'hi'],
225	    [' a  b ', 'a  b'], ['  hi', 'hi'], ['hi  ', 'hi'], ['​', '​'], ['<b>x</b>', '<b>x</b>'],
226	  ];
227	  const expected = [];
228	  for (const [i, [sent, stored]] of cases.entries()) {
229	    const over = { title: sent, ...hourSlot(i) };
230	    const res = await post(port, body(over));
231	    assert.equal(res.status, 201, `title #${i} status`);
232	    assert.deepEqual(res.json, { id: i + 1, ...valid(over), title: stored }, `title #${i} body`);
233	    expected.push(res.json);
234	  }
235	  const list = await request(port, 'GET', '/api/bookings');
236	  assert.deepEqual(list.json.bookings, expected, 'GET returns trimmed titles');
237	});
238	
239	// ---------- rule 6 ----------
240	
241	test('rule 6: accepted dates', async (t) => {
242	  const { port } = await boot(t);
243	  const dates = ['2000-01-01', '2099-12-31', '2024-02-29', '2000-02-29', '2096-02-29', '2026-01-31',
244	    '2026-04-30', '2026-12-31', '2026-11-30'];
245	  for (const date of dates) {
246	    assert.equal((await post(port, body({ date }))).status, 201, `date ${date}`);
247	  }
248	});
249	
250	test('rule 6: rejected dates', async (t) => {
