function chunkedPost(port, payload) {
  return new Promise((resolve, reject) => {
    const req = http.request({
      host: '127.0.0.1', port, method: 'POST', path: '/api/bookings', agent: false,
      headers: { 'content-type': 'application/json', 'transfer-encoding': 'chunked' },
    }, (res) => {
      let text = '';
      res.on('data', (c) => { text += c; });
      res.on('end', () => resolve({ status: res.statusCode, json: JSON.parse(text) }));
    });
    req.on('error', reject);
    const third = Math.floor(payload.length / 3);
    req.write(payload.subarray(0, third));
    req.write(payload.subarray(third, 2 * third));
    req.end(payload.subarray(2 * third));
  });
}

