143	function chunkedUpload(port, pieces, pieceSize) {
144	  return new Promise((resolve, reject) => {
145	    const req = http.request({
146	      host: '127.0.0.1', port, method: 'POST', path: '/api/bookings', agent: false,
147	      headers: { 'content-type': 'application/json', 'transfer-encoding': 'chunked' },
148	    }, (res) => {
149	      const chunks = [];
150	      res.on('data', (c) => chunks.push(c));
151	      res.on('end', () => {
152	        const text = Buffer.concat(chunks).toString('utf8');
153	        resolve({ status: res.statusCode, json: JSON.parse(text) });
154	      });
155	    });
156	    req.on('error', reject);
157	    const piece = Buffer.alloc(pieceSize, 0x61);
158	    let left = pieces;
159	    const pump = () => {
160	      while (left > 0) {
161	        left -= 1;
162	        if (!req.write(piece)) { req.once('drain', pump); return; }
163	      }
164	      req.end();
165	    };
166	    pump();
167	  });
168	}
